					Source:          SourceSLMEscalation,
					Reason:          "low_confidence",
					Confidence:      confidence,
					TaskType:        category,
					EstimatedTokens: estimatedTokens,
					BudgetSource:    req.GuardrailSource,
					BudgetTokens:    req.GuardrailBudget,
					CacheHit:        true,
					CacheHitKind:    hitKind,
				}
			}
			return Decision{
				Route:           cached,
				Source:          SourceSLM,
				Confidence:      confidence,
				TaskType:        category,
				EstimatedTokens: estimatedTokens,
				BudgetSource:    req.GuardrailSource,
				BudgetTokens:    req.GuardrailBudget,
				CacheHit:        true,
				CacheHitKind:    hitKind,
			}
		}
